using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionRejectionTests { [Fact] public void Rejection_inventory_is_defined_distinct_and_ascending(){var values=Enum.GetValues<DocumentaryMediaProjectionRejectionReason>();Assert.Equal(21,values.Length);Assert.Equal(values.Length,values.Distinct().Count());Assert.Equal(Enumerable.Range(0,values.Length),values.Select(x=>(int)x));var result=new DocumentaryMediaProjectionResult(DocumentaryMediaProjectionStatus.Rejected,[DocumentaryMediaProjectionRejectionReason.ProjectionPolicyRejected],null);Assert.True(result.IsRejected);Assert.False(result.HasMediaProject);} }
